use serde::{Deserialize, Serialize};
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)] pub enum FileKind { Directory, File, Symlink, Executable, Archive, Image, Other }
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)] pub struct FileEntry { pub name:String, pub path:String, pub kind:FileKind, pub size:u64, pub permissions:String, pub modified:String, pub owner:String, pub group:String, pub selected:bool }
impl FileEntry { pub fn icon(&self, nerd:bool)->&'static str{ if nerd { match self.kind { FileKind::Directory=>"󰉋", FileKind::Symlink=>"", FileKind::Executable=>"󰡱", FileKind::Archive=>"󰿺", FileKind::Image=>"󰋩", _=>"󰈙" } } else { match self.kind { FileKind::Directory=>"[D]", FileKind::Symlink=>"[L]", FileKind::Executable=>"[*]", FileKind::Archive=>"[A]", FileKind::Image=>"[I]", _=>"[F]" } } } }
pub fn parse_ls_line(line:&str)->Option<FileEntry>{ let parts:Vec<&str>=line.split_whitespace().collect(); if parts.len()<9{return None;} let perms=parts[0]; let kind= if perms.starts_with('d'){FileKind::Directory}else if perms.starts_with('l'){FileKind::Symlink}else if perms.contains('x'){FileKind::Executable}else{ let name=parts[8..].join(" "); kind_from_name(&name)}; Some(FileEntry{name:parts[8..].join(" "), path:parts[8..].join(" "), kind, size:parts[4].parse().unwrap_or(0), permissions:perms.into(), owner:parts[2].into(), group:parts[3].into(), modified:format!("{} {} {}",parts[5],parts[6],parts[7]), selected:false}) }
pub fn kind_from_name(name:&str)->FileKind{ let l=name.to_ascii_lowercase(); if [".zip",".tar",".gz",".tgz",".xz",".rar"].iter().any(|e|l.ends_with(e)){FileKind::Archive}else if [".png",".jpg",".jpeg",".gif",".webp",".svg"].iter().any(|e|l.ends_with(e)){FileKind::Image}else{FileKind::File} }
#[cfg(test)] mod tests { use super::*; #[test] fn parses_ls_entry(){ let e=parse_ls_line("-rw-r--r-- 1 user group 2048 May 16 09:00 package.json").unwrap(); assert_eq!(e.name,"package.json"); assert_eq!(e.size,2048); assert_eq!(e.kind,FileKind::File); } }
